/* 
	Mesh Clock

	https://openprocessing.org/sketch/2150410
	#genuary20 #genuary #creativecoding #generativeart

	https://genuary.art/prompts#jan20
*/

let S, BG;
let font, points1, points2, points3;
let ptsNumbers, maxBBox;
const FPS = 1;

function preload() {
  // Creates a p5.Font object.
  font = loadFont('https://openprocessing.org/sketch/2150410/files/RubikBurned-Regular.ttf');
}

function setup() {
  createCanvas(S = max(windowWidth, windowHeight), S);
	pixelDensity(1);
  describe("mesh of points connected by distance forming current time");
  frameRate(FPS);

	BG = "navy";
	drawBackground(BG)

	noFill()
	stroke(212) // 232
	strokeWeight(1)
	strokeCap(SQUARE);

	S/=3;
	textFont(font);
	// textAlign(CENTER, CENTER);
	// textStyle(BOLD);
	textSize(S)	

	getPts();
	getPoints();
}

function drawBackground(bg) {
	background(bg);

	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(width/2, height/2, max(width, height)/4, width/2, height/2, max(width, height)*2);

	// Add three color stops
	gradient.addColorStop(0, "navy");
	gradient.addColorStop(1, "cyan");

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);
}

function getPts(sampleFactor = 0.1) {
	ptsNumbers = [];
	maxBBox = {x: 0, y:0, w: 0, h: 0};
	for (let i = 0; i < 10; i++) {
		const MSG = "" + i;
		const bbox = font.textBounds(MSG, 0, 0);
		const pts = font.textToPoints(MSG, 0, 0, S, { sampleFactor});
		ptsNumbers.push({bbox, pts});
	}
	console.log(maxBBox)
	console.log(ptsNumbers)
}


function getPoints(sampleFactor = 0.1) {
	MSG1 = nf(hour(), 2);
	MSG2 = nf(minute(), 2);
	MSG3 = nf(second(), 2);

	bbox1 = font.textBounds(MSG1, 0, 0);
	bbox2 = font.textBounds(MSG2, 0, 0);
	bbox3 = font.textBounds(MSG3, 0, 0);
	/*
	console.log(bbox1)
	console.log(bbox2)
	console.log(bbox3)
	*/

	const dy = (height-bbox1.h-bbox2.h-bbox3.h)/2;
	points1 = font.textToPoints(MSG1, 0, 0, S, { sampleFactor});
	points1.map((p) => {p.y -= bbox1.y - dy; p.x += -bbox1.x + (width-bbox1.w)/2});
	points2 = font.textToPoints(MSG2, 0, 0, S, { sampleFactor});
	points2.map((p) => {p.y -= bbox1.y + bbox2.y - dy; p.x += -bbox2.x + (width-bbox2.w)/2});
	points3 = font.textToPoints(MSG3, 0, 0, S, { sampleFactor});
	points3.map((p) => {p.y -= bbox1.y + bbox2.y + bbox3.y - dy; p.x += -bbox3.x + (width-bbox3.w)/2});
	// console.log("l: " + points1.length + ", " + points2.length + ", " + points3.length)

	// points = points1.concat(points2, points3);

}

function draw() {
	let strtTime = millis();
	if (frameCount % FPS === 0) getPoints();
	let tmr1 = millis() - strtTime;

	drawBackground(BG)
	showMesh(points1, color("magenta"));
	showMesh(points2, color("cyan"));
	showMesh(points3, color("orange"));

	let tmr2 = millis() - strtTime - tmr1;
	console.log("t: " + strtTime + ", " + tmr1 + ", " + tmr2)
}

function showMesh(points, clr) {
	const maxd = S/10;
	push()
	points.forEach(p =>  {
		points.forEach(o =>  {
			if (o!==p) {
				const d = dist(o.x, o.y, p.x, p.y);
				if (d < maxd) {				
					clr.setAlpha(255-d/maxd*255)
					stroke(clr)
					line(o.x, o.y, p.x, p.y);
				}
			}
		});
		// point(p.x, p.y)
  });
	pop()
}
